with unpacked as (select id, customer_id, created_at, coupon_codes, items, ship_to, attributes['utm_source'] as utm_source, coalesce(attributes['gift'], 'unknown') as gift_or_default from carts where array_contains(coupon_codes, 'BUNDLE')) select *, first_value(gift_or_default, true) over (partition by customer_id order by created_at asc, id asc rows between unbounded preceding and current row) as first_known_gift_or_default, row_number() over (partition by customer_id order by created_at asc, id asc) as event_seq, row_number() over (partition by to_date(created_at), customer_id order by created_at desc, id asc) as event_seq_2, first_value(gift_or_default) ignore nulls over (partition by customer_id order by created_at asc, id asc rows between unbounded preceding and current row) as first_known_gift_or_default_2 from unpacked where customer_id in (13, 18, 32, 33)
